mapper.select:
SELECT DISTINCT m.*
FROM sys_user_role ur
INNER JOIN sys_role r ON r.id = ur.role_id AND r.deleted = 0 AND r.status = #{status}
INNER JOIN sys_role_menu rm ON rm.role_id = ur.role_id AND rm.deleted = 0
INNER JOIN sys_menu m ON m.id = rm.menu_id AND m.deleted = 0 AND m.status = #{status}
WHERE ur.user_id = #{userId}
  AND ur.deleted = 0
ORDER BY m.sort ASC
